def C(identifier: str, topic: str, question: str, alternate: str, answer: str,
      sources: str, *, holdout: bool = False) -> dict:
    return {"id": "v4_" + identifier, "topic": topic, "question": question,
            "aliases": [alternate], "answer": answer, "sources": sources.split(), "holdout": holdout}


